<?php require_once __DIR__.'/../config/database.php'; require_once __DIR__.'/../includes/auth.php'; $pdo=getConnection();
$total=(int)$pdo->query("SELECT COUNT(*) FROM ocorrencia WHERE status='aprovada'")->fetchColumn();
$tipos=$pdo->query("SELECT t.nome_tipo,COUNT(o.id_ocorrencia) total FROM tipo_ocorrencia t LEFT JOIN ocorrencia o ON o.id_tipo=t.id_tipo AND o.status='aprovada' GROUP BY t.id_tipo,t.nome_tipo ORDER BY total DESC,t.nome_tipo")->fetchAll();
$horarios=$pdo->query("SELECT HOUR(horario) hora,COUNT(*) total FROM ocorrencia WHERE status='aprovada' GROUP BY HOUR(horario) ORDER BY total DESC LIMIT 6")->fetchAll();
$page_title='SafeRoute — Estatísticas'; require_once __DIR__.'/../includes/header.php'; require_once __DIR__.'/../includes/navbar.php'; ?>
<main class="container page-main"><section class="page-hero"><span class="eyebrow">ESTATÍSTICAS</span><h1>Panorama das ocorrências</h1><p>Indicadores calculados a partir dos registros aprovados disponíveis no sistema.</p></section><section class="stats-grid"><article class="stat-card"><span>Ocorrências aprovadas</span><strong><?= $total ?></strong></article><article class="stat-card"><span>Tipos cadastrados</span><strong><?= count($tipos) ?></strong></article></section><div class="content-grid"><section class="card"><h2>Ocorrências por tipo</h2><table class="admin-table"><thead><tr><th>Tipo</th><th>Total</th></tr></thead><tbody><?php foreach($tipos as $t): ?><tr><td><?= htmlspecialchars($t['nome_tipo']) ?></td><td><?= (int)$t['total'] ?></td></tr><?php endforeach; ?></tbody></table></section><section class="card"><h2>Horários com maior frequência</h2><table class="admin-table"><thead><tr><th>Horário</th><th>Total</th></tr></thead><tbody><?php foreach($horarios as $h): ?><tr><td><?= sprintf('%02d:00–%02d:59',(int)$h['hora'],(int)$h['hora']) ?></td><td><?= (int)$h['total'] ?></td></tr><?php endforeach; ?><?php if(!$horarios): ?><tr><td colspan="2" class="admin-empty">Sem dados suficientes.</td></tr><?php endif; ?></tbody></table></section></div><p class="notice">⚠️ Os resultados são estimativas baseadas nos dados disponíveis e não representam garantia de segurança.</p></main><?php require_once __DIR__.'/../includes/footer.php'; ?>
